body.script:
//

// --- 1. DATA EXTRACTION ---
var productsData = [];
var flatOrders = []; // Holds every product from every order individually

var i = 0;
while (document.getElementById('pname_' + i)) {
    var pName = document.getElementById('pname_' + i).value;
    var uom = document.getElementById('puom_' + i).value;
    var ordersRaw = document.getElementById('porders_' + i).value;

    var orders = [];
    try { orders = JSON.parse(ordersRaw); } catch(e) { orders = []; }

    productsData.push({
        product_name: pName,
        total_qty: document.getElementById('pqty_' + i).value,
        uom: uom,
        orders: orders
    });

    // Flatten orders
    orders.forEach(function(o) {
        var orderCopy = Object.assign({}, o);
        orderCopy.uom = uom;
        flatOrders.push(orderCopy);
    });
    i++;
}

// --- 2. HELPER FUNCTIONS ---
function buildRowHTML(order) {
    return '<tr>' +
        '<td><b>' + order.origin + '</b></td>' +
        '<td>' + order.date_order + '</td>' +
        '<td>' + order.customer + '</td>' +
        '<td>' + order.customer_city + '</td>' +
        '<td>' + order.salesperson + '</td>' +
        '<td>' + order.item_name + '</td>' +
        '<td>' + order.delivery_date + '</td>' +
        '<td>' + order.qty + ' ' + order.uom +'</td>' +
        '<td>' +
            (order.color ?
            '<div style="display: flex; align-items: center; gap: 6px;">' +
                '<div style="width: 16px; height: 16px; border-radius: 4px; border: 1px solid #adb5bd; background-color: ' + order.color + ';"></div>' +
                '<span>' + order.color + '</span>' +
            '</div>'
            : '—') +
        '</td>' +
        '<td>' +
        (order.note ? '<a href="javascript:void(0)" class="note-link" data-note="' + encodeURIComponent(order.note) + '" style="color:#042c53;font-weight:600;text-decoration:underline;">View</a>' : '') +
        '</td>' +
        '</tr>';
}

// --- 3. RENDER FULL LIST VIEW ---
function renderAllOrdersTable() {
    var term = document.getElementById('searchSO').value.toLowerCase().trim();
    var groupBy = document.getElementById('groupBySelect').value;

    // Apply Search Filter
    var filtered = flatOrders.filter(function(o) {
        return o.origin.toLowerCase().includes(term);
    });

    var tbody = document.getElementById('allOrdersTableBody');
    var html = '';

    if (filtered.length === 0) {
        tbody.innerHTML = '<tr><td colspan="10" style="text-align:center; padding: 40px; color: #6c757d; font-size: 15px;">No sale orders match your search.</td></tr>';
        return;
    }

    if (groupBy === 'none') {
        // FLAT VIEW: Sorted entirely by SO Number Descending (e.g., S00085 > S00078)
        filtered.sort(function(a, b) {
            return b.origin.localeCompare(a.origin);
        });

        filtered.forEach(function(o) {
            html += buildRowHTML(o);
        });

    } else if (groupBy === 'so') {
        // GROUP BY: Sale Order
        var soGroups = {};
        filtered.forEach(function(o) {
            if (!soGroups[o.origin]) soGroups[o.origin] = [];
            soGroups[o.origin].push(o);
        });

        var soArray = Object.keys(soGroups).map(function(key) {
            return { origin: key, orders: soGroups[key] };
        });

        // Sort Sale Orders Descending
        soArray.sort(function(a, b) { return b.origin.localeCompare(a.origin); });

        soArray.forEach(function(g) {
            var firstOrder = g.orders[0];
            html += '<tr style="background-color: #e9ecef; border-top: 3px solid #042c53;">' +
                    '<td colspan="10" style="font-weight: 700; color: #042c53; font-size: 14px; padding-top: 15px; padding-bottom: 15px;">' +
                    'Sale Order: <span style="font-size: 16px; margin-right: 15px;">' + g.origin + '</span> | <span style="margin-left: 15px; font-weight:normal;">Customer: ' + firstOrder.customer + '</span>' +
                    '</td></tr>';

            g.orders.forEach(function(o) { html += buildRowHTML(o); });
        });

    } else if (groupBy === 'product') {
        // GROUP BY: Product
        var prodGroups = {};
        filtered.forEach(function(o) {
            if (!prodGroups[o.item_name]) prodGroups[o.item_name] = [];
            prodGroups[o.item_name].push(o);
        });

        var prodArray = Object.keys(prodGroups).map(function(key) {
            return { item_name: key, orders: prodGroups[key] };
        });

        // Sort Products Alphabetically
        prodArray.sort(function(a, b) { return a.item_name.localeCompare(b.item_name); });

        prodArray.forEach(function(g) {
            html += '<tr style="background-color: #d1ecf1; border-top: 3px solid #042c53;">' +
                    '<td colspan="10" style="font-weight: 700; color: #042c53; font-size: 14px; padding-top: 15px; padding-bottom: 15px;">' +
                    'Product: <span style="font-size: 16px;">' + g.item_name + '</span>' +
                    '</td></tr>';

            // Sort items inside the group by SO Number Descending
            g.orders.sort(function(a, b) { return b.origin.localeCompare(a.origin); });
            g.orders.forEach(function(o) { html += buildRowHTML(o); });
        });
    }

    tbody.innerHTML = html;
}

// --- 4. EVENT LISTENERS ---
var isListView = false;
var isModalOpen = false;

// Toggle between Grid and Full List
document.getElementById('btnToggleView').addEventListener('click', function() {
    if (!isListView) {
        document.getElementById('view-grid').style.display = 'none';
        document.getElementById('view-list').style.display = 'block';
        this.innerText = "Back to Grid View";
        isListView = true;
        renderAllOrdersTable();
    } else {
        document.getElementById('view-grid').style.display = 'block';
        document.getElementById('view-list').style.display = 'none';
        this.innerText = "View All Sale Orders";
        isListView = false;
    }
});

// Input triggers re-render
document.getElementById('searchSO').addEventListener('input', renderAllOrdersTable);
document.getElementById('groupBySelect').addEventListener('change', renderAllOrdersTable);

// Grid Card Clicks (Opens single-product modal)
document.getElementById('moGrid').addEventListener('click', function(e) {
    var card = e.target.closest('.mo-card');
    if (!card) return;
    var index = parseInt(card.getAttribute('data-index'), 10);

    var prod = productsData[index];
    document.getElementById('modalTitle').innerText = prod.product_name;

    var tbody = document.getElementById('modalTableBody');
    tbody.innerHTML = '';

    // Sort modal orders by SO Number Descending
    var sortedOrders = [...prod.orders].sort((a, b) => b.origin.localeCompare(a.origin));

    sortedOrders.forEach(function(o) {
        var orderCopy = Object.assign({}, o);
        orderCopy.uom = prod.uom;
        tbody.innerHTML += buildRowHTML(orderCopy);
    });

    document.getElementById('detailModal').classList.add('open');
    isModalOpen = true;
});

// Note Listeners
document.addEventListener('click', function(e){
    if(e.target.classList.contains('note-link')){
        var note = decodeURIComponent(e.target.getAttribute('data-note') || '');
        document.getElementById('noteContent').innerText = note || 'No notes available.';
        document.getElementById('noteModal').classList.add('open');
        isModalOpen = true;
    }
});

// Modal Close Events
document.getElementById('closeModal').addEventListener('click', function() {
    document.getElementById('detailModal').classList.remove('open');
    isModalOpen = false; sec = 20;
});
document.getElementById('closeNoteModal').addEventListener('click', function() {
    document.getElementById('noteModal').classList.remove('open');
    isModalOpen = false; sec = 20;
});
document.getElementById('detailModal').addEventListener('click', function(e) {
    if (e.target === this) { this.classList.remove('open'); isModalOpen = false; sec = 20; }
});
document.getElementById('noteModal').addEventListener('click', function(e) {
    if (e.target === this) { this.classList.remove('open'); isModalOpen = false; sec = 20; }
});

// Auto Refresh Logic
var sec = 20;
setInterval(function() {
    if (isModalOpen || isListView) return;
    sec--;
    var el = document.getElementById('countdown');
    if (el) el.innerText = sec;
    if (sec <= 0) window.location.reload();
}, 1000);

//
